-- Everything a member already holds stays theirs for good.
SELECT DISTINCT g."userId", g."catalogItemId", 'legacy' FROM "user_gear_items" g
JOIN "equipment_catalog" c ON c.id = g."catalogItemId" AND c.kind = 'gear'
ON CONFLICT DO NOTHING;
